#import <UIKit/UIKit.h>
static NSURL *logURL(void) { return [NSURL fileURLWithPath:[NSTemporaryDirectory() stringByAppendingPathComponent:@"orientation-events.jsonl"]]; }
@interface InputVC:UIViewController
@property(nonatomic,strong)UILabel *label; @property(nonatomic)NSUInteger eventCount;
@end
@implementation InputVC
-(UIInterfaceOrientationMask)supportedInterfaceOrientations { return UIInterfaceOrientationMaskPortrait|UIInterfaceOrientationMaskLandscapeLeft|UIInterfaceOrientationMaskLandscapeRight; }
-(void)emit:(NSString *)reason { UIWindowScene *s=self.view.window.windowScene;if(!s)return; self.eventCount++; NSDictionary *j=@{@"time":@([NSDate date].timeIntervalSince1970),@"reason":reason,@"device":@(UIDevice.currentDevice.orientation),@"interface":@(s.interfaceOrientation),@"width":@(self.view.bounds.size.width),@"height":@(self.view.bounds.size.height),@"mask":@([self supportedInterfaceOrientations]),@"event":@(self.eventCount)}; NSData *b=[NSJSONSerialization dataWithJSONObject:j options:0 error:nil];NSFileHandle *h=[NSFileHandle fileHandleForWritingAtPath:logURL().path];if(!h){[NSData.data writeToURL:logURL() atomically:YES];h=[NSFileHandle fileHandleForWritingAtPath:logURL().path];}[h seekToEndOfFile];[h writeData:b];[h writeData:[@"\n" dataUsingEncoding:NSUTF8StringEncoding]];[h closeFile];self.label.text=[NSString stringWithFormat:@"Duo QA Input\ndevice=%ld interface=%ld\n%.0f x %.0f  event=%lu",(long)UIDevice.currentDevice.orientation,(long)s.interfaceOrientation,self.view.bounds.size.width,self.view.bounds.size.height,(unsigned long)self.eventCount]; }
-(void)deviceChanged:(NSNotification *)n { [self emit:@"deviceNotification"]; }
-(void)viewDidLoad { [super viewDidLoad];self.view.backgroundColor=UIColor.systemBackgroundColor;self.label=[UILabel new];self.label.numberOfLines=0;self.label.textAlignment=NSTextAlignmentCenter;self.label.font=[UIFont systemFontOfSize:24];self.label.frame=self.view.bounds;self.label.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;self.label.accessibilityIdentifier=@"orientation-input-qa-status";[self.view addSubview:self.label];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(deviceChanged:) name:UIDeviceOrientationDidChangeNotification object:nil];[UIDevice.currentDevice beginGeneratingDeviceOrientationNotifications]; }
-(void)viewDidLayoutSubviews { [super viewDidLayoutSubviews];[self emit:@"layout"]; }
-(void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self];[UIDevice.currentDevice endGeneratingDeviceOrientationNotifications]; }
@end
@interface InputScene:NSObject<UIWindowSceneDelegate> @property(nonatomic,strong)UIWindow *window; @end
@implementation InputScene
-(void)scene:(UIScene *)scene willConnectToSession:(UISceneSession *)session options:(UISceneConnectionOptions *)options {self.window=[[UIWindow alloc]initWithWindowScene:(UIWindowScene *)scene];self.window.rootViewController=[InputVC new];[self.window makeKeyAndVisible];}
@end
@interface InputApp:NSObject<UIApplicationDelegate> @end
@implementation InputApp
-(BOOL)application:(UIApplication *)app didFinishLaunchingWithOptions:(NSDictionary *)options {NSURL *dir=[NSFileManager.defaultManager URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask].firstObject;NSString *text=@"Duo import 20261031\n鼠标里面的硅二极管坏了，导致光标分辨率降低。\n";[text writeToURL:[dir URLByAppendingPathComponent:@"duo-input-20261031.txt"] atomically:YES encoding:NSUTF8StringEncoding error:nil];return YES;}
-(UISceneConfiguration *)application:(UIApplication *)app configurationForConnectingSceneSession:(UISceneSession *)session options:(UISceneConnectionOptions *)options {UISceneConfiguration *c=[[UISceneConfiguration alloc]initWithName:@"InputQA" sessionRole:session.role];c.delegateClass=InputScene.class;return c;}
@end
int main(int argc,char **argv){@autoreleasepool{return UIApplicationMain(argc,argv,nil,NSStringFromClass(InputApp.class));}}

